#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int N=10005,S=N-2,T=N-1;
const int M=2e6+10;
const int inf=2e9;

int head[N],to[M],nxt[M],w[M],c[M],cnt=1;

inline void addedge(int x, int y, int flow, int cost){
	to[++cnt]=y,nxt[cnt]=head[x],head[x]=cnt;
	w[cnt]=flow,c[cnt]=cost;
	to[++cnt]=x,nxt[cnt]=head[y],head[y]=cnt;
	w[cnt]=0,c[cnt]=-cost;
}

queue <int> q;
long long dis[N];
bool mark[N];

inline bool spfa(){
	memset(mark,0,sizeof(mark));
	memset(dis,0x3f,sizeof(dis));
	q.push(T); dis[T]=0; mark[T]=1;
	while (!q.empty()){
		int x=q.front();
		mark[x]=0; q.pop();
		for (int i=head[x];i;i=nxt[i]){
			int y=to[i];
			if (w[i^1]&&dis[y]>dis[x]+c[i^1]){
				dis[y]=dis[x]+c[i^1];
				if (!mark[y]){
					q.push(y); mark[y]=1;
				}
			}
		}
	}
	return dis[S]<1e18;
}

inline int dfs(int x, int lim, ll &cost){
	int flow=0; mark[x]=1;
	if (x==T) return lim;
	for (int i=head[x];i;i=nxt[i]){
		int y=to[i];
		if (!w[i]||mark[y]) continue;
		if (dis[x]!=dis[y]+c[i]) continue;
		int t=dfs(y,min(w[i],lim-flow),cost);
		w[i]-=t; w[i^1]+=t;
		flow+=t; cost+=t*c[i];
		if (flow==lim) return lim;
	}
	return flow;
}

inline ll costflow(){
	int flow=0; ll cost=0;
	while (spfa())
		do{
			memset(mark,0,sizeof(mark));
			flow+=dfs(S,inf,cost);
		}while (mark[T]);
	return cost;
}

int main(){
	int n,m,k,c,d,lim=101;
	cin>>n>>m>>k>>c>>d;
	for (int i=0;i<k;i++){
		int x; cin>>x; x--;
		addedge(S,x,1,0);
	}
	for (int i=0;i<lim;i++)
		addedge(i*n,T,k,c*i);
	for (int i=0;i<n;i++)
		for (int j=0;j<lim-1;j++)
			addedge(i+j*n,i+(j+1)*n,k,0);
	while (m--){
		int x,y; cin>>x>>y; x--,y--;
		for (int i=0;i<lim-1;i++)
			for (int j=k-1;~j;j--){
				addedge(x+i*n,y+(i+1)*n,1,d*(j<<1|1));
				addedge(y+i*n,x+(i+1)*n,1,d*(j<<1|1));
			}
	}
	cout<<costflow();
	return 0;
}

